def solve_frame_completion(grid, interior_marker_thr=4, max_gap=6):
    """Complete a rectangle frame from sparse markers: fill gaps <= max_gap on
    bbox-perimeter lines always; on interior lines only if the line has >=
    interior_marker_thr markers; extend extreme perimeter markers to bbox edges."""
    H, W = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    mk = min(counts, key=counts.get)  # least common color = marker
    pts = [(r, c) for r in range(H) for c in range(W) if grid[r][c] == mk]
    rs = [p[0] for p in pts]; cs = [p[1] for p in pts]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
    out = [row[:] for row in grid]

    def process(fixed, horiz, perim):
        ms = sorted(p[1] if horiz else p[0]
                    for p in pts if (p[0] == fixed if horiz else p[1] == fixed))
        if not ms:
            return
        for a, b in zip(ms, ms[1:]):
            gap = b - a - 1
            if gap < 1:
                continue
            if perim or (len(ms) >= interior_marker_thr and gap <= max_gap):
                for x in range(a + 1, b):
                    rr, cc = (fixed, x) if horiz else (x, fixed)
                    out[rr][cc] = 2
        if perim:
            lo, hi = (c0, c1) if horiz else (r0, r1)
            for m, edge in ((ms[0], lo), (ms[-1], hi)):
