                        if grid[rr][cc] != mk:
                            out[rr][cc] = 2

    for r in range(H):
        if any(p[0] == r for p in pts):
            process(r, True, r in (r0, r1))
    for c in range(W):
        if any(p[1] == c for p in pts):
            process(c, False, c in (c0, c1))
    return out
